import java.util.*;

class Solution {
    public int jump(int[] nums) {
        int n = nums.length;
        int[] steps = new int[n];
        Arrays.fill(steps, Integer.MAX_VALUE);
        Queue<Integer> q = new LinkedList<>();
        q.offer(0);
        steps[0] = 0;
        while (!q.isEmpty()) {
            int i = q.poll();
            if (i == n - 1) return steps[i];
            for (int step = 1; step <= nums[i]; step++) {
                int nxt = i + step;
                if (nxt < n && steps[nxt] == Integer.MAX_VALUE) {
                    steps[nxt] = steps[i] + 1; // 步数 +1
                    q.offer(nxt);
                }
            }
        }
        return -1;
    }
}

class Solution {
    public int jump(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (dp[j] != Integer.MAX_VALUE && j + nums[j] >= i) {
                    dp[i] = Math.min(dp[i], dp[j] + 1);
                }
            }
        }
        return dp[n - 1];
    }
}

class Solution {
    public int jump(int[] nums) {
        int n = nums.length;
        int jumps = 0;          // 已跳步数
        int curEnd = 0;         // 当前这一步能到达的最远边界
        int farthest = 0;       // 遍历过程中能跳到的最远处
        for (int i = 0; i < n - 1; i++) { // 末尾不用再跳，故到 n-2
            farthest = Math.max(farthest, i + nums[i]);
            if (i == curEnd) {  // 到达当前步的边界，必须再跳一步
                jumps++;
                curEnd = farthest; // 下一步的边界更新为最远可达
            }
        }
        return jumps;
    }
}

class Solution {
    public int jump(int[] nums) {
        int jumps = 0, curEnd = 0, farthest = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            if (i == curEnd) {
                jumps++;
                curEnd = farthest;
            }
        }
        return jumps;
    }
}

