class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;
        int[][] copy = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                copy[i][j] = matrix[n - 1 - j][i]; // 新位置取旧位置
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                matrix[i][j] = copy[i][j];
    }
}

class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;
        // 1. 沿主对角线转置
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int tmp = matrix[i][j];
                matrix[i][j] = matrix[j][i];
                matrix[j][i] = tmp;
            }
        }
        // 2. 每行水平翻转
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n / 2; j++) {
                int tmp = matrix[i][j];
                matrix[i][j] = matrix[i][n - 1 - j];
                matrix[i][n - 1 - j] = tmp;
            }
        }
    }
}

class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;
        for (int layer = 0; layer < n / 2; layer++) {
            int first = layer, last = n - 1 - layer;
            for (int i = first; i < last; i++) {
                int offset = i - first;
                int top = matrix[first][i];                          // 暂存上
                matrix[first][i] = matrix[last - offset][first];    // 左 -> 上
                matrix[last - offset][first] = matrix[last][last - offset]; // 下 -> 左
                matrix[last][last - offset] = matrix[i][last];      // 右 -> 下
                matrix[i][last] = top;                              // 上 -> 右
            }
        }
    }
}

