import java.util.*;

class Solution {
    public boolean canJump(int[] nums) {
        int n = nums.length;
        boolean[] visited = new boolean[n];
        Queue<Integer> q = new LinkedList<>();
        q.offer(0);
        visited[0] = true;
        while (!q.isEmpty()) {
            int i = q.poll();
            if (i == n - 1) return true;        // 到达末尾
            for (int step = 1; step <= nums[i]; step++) {
                int nxt = i + step;
                if (nxt < n && !visited[nxt]) {
                    visited[nxt] = true;
                    q.offer(nxt);
                }
            }
        }
        return false;
    }
}

class Solution {
    public boolean canJump(int[] nums) {
        int n = nums.length;
        boolean[] dp = new boolean[n];
        dp[0] = true;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (dp[j] && j + nums[j] >= i) { // j 能到且从 j 能跳到 i
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[n - 1];
    }
}

class Solution {
    public boolean canJump(int[] nums) {
        int n = nums.length;
        int reach = 0; // 当前能到达的最远下标
        for (int i = 0; i < n; i++) {
            if (i > reach) return false;     // 当前位置已在可达范围之外
            reach = Math.max(reach, i + nums[i]); // 用这一步能跳的最远更新
            if (reach >= n - 1) return true; // 已经能覆盖末尾，提前结束
        }
        return reach >= n - 1;
    }
}

class Solution {
    public boolean canJump(int[] nums) {
        int reach = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > reach) return false;            // 覆盖出现空洞，过不去
            reach = Math.max(reach, i + nums[i]);
        }
        return true; // 能走到这里说明整段都被覆盖
    }
}

